// Hops chat → Supabase Edge Function "hops-chat" (Gemini). NOT generated by Figma Make.
import { FunctionsHttpError } from "@supabase/supabase-js";
import { supabase } from "./supabase";
import { ensureGuestSession } from "./auth";
import type { DbSpot } from "./db";

export type HopsTurn = { role: "user" | "model"; text: string };

/** What Hops answered: the chat text plus up to 3 recommended spots (full public.spots rows, validated server-side). */
export type HopsAnswer = { reply: string; spots: DbSpot[] };

export class HopsChatError extends Error {
  constructor(message: string, readonly code: string) {
    super(message);
  }
}

/** Sends the conversation (oldest first) and returns Hops' reply + recommended spots. Throws HopsChatError with a friendly message. */
export async function askHops(history: HopsTurn[]): Promise<HopsAnswer> {
  if (!supabase) throw new HopsChatError("Hops needs the Study Hopper server to chat — it isn't configured here.", "no_supabase");
  const { user } = await ensureGuestSession();
  if (!user) throw new HopsChatError("Hops can't sign you in right now, so chat is napping. Try again soon!", "no_session");

  const messages = history
    .filter((turn) => turn.text.trim())
    .slice(-20)
    .map((turn) => ({ role: turn.role, text: turn.text.slice(0, 1500) }));

  const { data, error } = await supabase.functions.invoke<{ reply?: string; spots?: DbSpot[]; error?: string }>("hops-chat", {
    body: { messages },
  });
  if (error) {
    if (error instanceof FunctionsHttpError) {
      const body = await error.context.json().catch(() => null);
      throw new HopsChatError(body?.error ?? "Hops hopped into a hiccup. Try again in a moment!", body?.code ?? "http");
    }
    throw new HopsChatError("Hops can't reach the burrow right now. Check your connection and try again!", "network");
  }
  if (!data?.reply) throw new HopsChatError(data?.error ?? "Hops lost its words for a sec. Try again?", "empty");
  const spots = Array.isArray(data.spots) ? data.spots.filter((spot) => spot && typeof spot.id === "string" && spot.name) : [];
  return { reply: data.reply, spots: spots.slice(0, 3) };
}
